Definition ldec (c : CC.cutpoint) (cells : list kentry) (off : Z) (pvs : list nat) : option (Z * nat * PMR.act) :=
  match PSO.pview (CC.cp_know c) with
  | Some t =>
    match PSO.tst c cells t,
          match byte_cell (CC.cp_know c) with Some p => Some (p, true) | None => match byte_cell cells with Some p => Some (p, false) | None => None end end with
    | Some st, Some ((wb, bv), tb) =>
        let bcells := if tb then CC.cp_know c else cells in      (* [comment removed for export] *)
        let scells := cells ++ (if tb then tmpl_ranges bv (CC.cp_know c) else []) ++ List.flat_map (fun v => tmpl_ranges v (CC.cp_know c)) pvs in
        if (PSO.view_ok (CC.cp_nx c) (CC.cp_know c) t && expr_eqb (PSO.v_wptr t) (offe wb off) && (off <=? 0) && (-8 <=? off) &&
            PSO.has bcells (KRange (EVar bv) 0 255) && PSO.has bcells (KBlob (SA WP0 0) WLEN 1) && implb tb (Nat.ltb bv (CC.cp_nx c) && APC.expr_vars_lt (CC.cp_nx c) wb) &&
            forallb (fun pv => Nat.ltb pv (CC.cp_nx c) && PSO.has scells (KRange (EVar pv) 0 255)) pvs &&
            (1 <=? st) && (st <=? 28))%bool
        then let badm := List.filter (fun b => RLF.byte_adm bv scells b) bytes256 in
             let padm := match pvs with [] => [] | _ => List.filter (adm_all pvs scells) bytes256 end in
             match badm with
             | b0 :: _ =>
                 let p0 := match pvs with [] => PML.ST_ROOT | _ => hd PML.ST_ROOT padm end in
                 let a := PMR.dispatch st p0 b0 in
                 if forallb (fun b => match pvs with
                                      | [] => allp3 (fun p => OBSXA.act_eqb (PMR.dispatch st p b) a)
                                      | _ => forallb (fun p => OBSXA.act_eqb (PMR.dispatch st p b) a) padm
                                      end) badm
                 then Some (st, bv, a) else None
             | [] => None
             end
        else None
    | _, _ => None
    end
  | None => None
  end.

