Lemma byte_of_cells : forall (EB : env) (MB : word -> option byte) bcells wb bv p0 wl pos,
  know_ok (hl_segs L) EB MB bcells -> In (KWord (SA wb 0) 1 (EVar bv)) bcells -> In (KRange (EVar bv) 0 255) bcells -> In (KBlob (SA WP0 0) WLEN 1) bcells ->
  eb EB = eb E0 -> CL5A.uv EB WP0 = p0 -> CL5A.uv EB WLEN = wl -> CL5A.uv EB wb = pos -> 0 <= pos - p0 < wl ->
  bv_unsigned (ev EB bv) = List.nth (Z.to_nat (pos - p0)) w0 0 /\ 0 <= bv_unsigned (ev EB bv) <= 255.
