Lemma leaf_decides : forall i c k ps0 tg E1 R1 A1 M1 m1 E' R' M' m' ps1 code g1 (cc : PMR.ctrl) evs al off st bv a,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 tg -> (2 <= i < PSO.NCUT)%nat ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' ->
  PSOX.CORE I i E1 M1 (PML.ps_win ps1) ps1 code g1 -> PML.wf_ps ps1 ->
  PSOX.BEF I i E1 cc ps1 off evs al -> PMR.rm_core cc ps1 ->
  ldec c (SR.ps_cells ps0) off (PSOWT.ppv i) = Some (st, bv, a) ->
  exists b, PSOX.rem I ps1 off = b :: PSOX.rem I ps1 (off + 1) /\ bv_unsigned (ev E' bv) = b /\ 0 <= b <= 255 /\ PML.ps_st ps1 = st /\
