Lemma XCELLS_leaf : forall i c ps0 E1 A1 M1 m1 E' R' M' m' cp cp2 tg,
  (2 <= i < PSO.NCUT)%nat -> nth_error G.CPS i = Some c -> AAMB I i E1 A1 M1 m1 -> PSOX.FLF I E1 -> env_agree (CC.cp_nx c) E1 E' ->
