Lemma sync_lit : forall (J : PSOIW.inst) (g' : PMES.eghost) evs al (ev : PMES.eev) pay,
  PSOX.SYNC J evs al -> match ev with PMES.EvNull | PMES.EvBool _ => True | _ => False end ->
