Lemma BEF_ret : forall i j Ex Ey Mx ps1 ps2 code g1 c evs al d,
  PSOX.CORE I i Ex Mx (PML.ps_win ps1) ps1 code g1 ->
  PML.ps_win ps2 = match PML.ps_win ps1 with Some (p, e) => Some (p + Z.max 0 d, e) | None => None end ->
