Lemma eof_werr : forall i c k ps0 tg E1 R1 A1 M1 m1 E' R' M' m' ps1 g1 cp cp2 tgb,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 tg -> (2 <= i < PSO.NCUT)%nat -> PSO.kind_of i = PSO.KSm ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' ->
